从数据库中查询给定试题id列表，要求每个试题随机抽样N条数据

pipeline = [
	{&#039;$match&#039;: {&#039;topic_id&#039;: {&#039;$in&#039;: topic_id_list}}},
	{&#039;$addFields&#039;: {&#039;random&#039;: {&#039;$rand&#039;: {}}}},
	{&#039;$setWindowFields&#039;: {
		&#039;partitionBy&#039;: &#039;$topic_id&#039;,
		&#039;sortBy&#039;: {&#039;random&#039;: 1},
		&#039;output&#039;: {
			&#039;rank&#039;: {&#039;$rank&#039;: {}}
			}
		}
	}，
	{&#039;$match&#039;: {&#039;rank&#039;: {&#039;$lt&#039;: N}}},
	{&#039;$unset&#039;: [&#039;random&#039;, &#039;rank&#039;]},
	{&#039;$project&#039;: {&#039;_id&#039;: 0}}
]

# 执行聚合（允许磁盘使用，处理大量数据）
cursor = collection.aggregate(pipeline, allowDiskUse=True)

